"""
Convert a markdown manuscript to a KDP-compatible EPUB3 file.
Usage: python3 convert_to_epub.py <input.md> <output.epub> <title> <author> [cover_image.png]
"""

import markdown
import zipfile
import os
import re
import sys
import io
import html as html_module
from xml.sax.saxutils import escape as xml_escape
from datetime import datetime

def md_to_html_safe(md_text):
    """Convert markdown to HTML and wrap in a body."""
    extensions = ['extra', 'smarty', 'codehilite', 'toc']
    html_body = markdown.markdown(md_text, extensions=extensions)
    return html_body

def slugify(text):
    """Create a safe filename slug from text."""
    text = text.lower().strip()
    text = re.sub(r'[^\w\s-]', '', text)
    text = re.sub(r'[-\s]+', '-', text)
    return text[:50]

def split_into_chapters(content):
    """
    Split markdown content into chapters.
    Returns list of (title, body_markdown) tuples.
    """
    lines = content.split('\n')

    # Find all h1/h2 chapter markers
    chapter_starts = []
    for i, line in enumerate(lines):
        stripped = line.strip()
        # Match: # Title, ## Chapter X, ## Chapter X -- Title, ## Chapter X — Title
        if re.match(r'^#{1,2}\s+(Chapter|CHAPTER|Part|PART|Introduction|Preface|Epilogue|Appendix|Dedication|Copyright|Table of Contents|Front Matter|Back Matter)', stripped, re.IGNORECASE):
            chapter_starts.append(i)
        elif re.match(r'^#\s+\w', stripped) and i == 0:
            pass  # Book title (first line)
        elif re.match(r'^#\s+\w', stripped):
            chapter_starts.append(i)
        elif stripped.startswith('## ') and i > 0:
            chapter_starts.append(i)

    if not chapter_starts:
        # No chapter markers - return whole thing as one chapter
        return [("Full Content", content)]

    chapters = []
    for idx, start in enumerate(chapter_starts):
        end = chapter_starts[idx + 1] if idx + 1 < len(chapter_starts) else len(lines)
        chapter_text = '\n'.join(lines[start:end]).strip()
        title_line = lines[start].strip()
        title = re.sub(r'^#+\s+', '', title_line).strip()
        chapters.append((title, chapter_text))

    return chapters

def create_epub(input_path, output_path, title, author, cover_image=None, language="en"):
    """Create a complete EPUB3 file from a markdown manuscript."""

    print(f"Reading {input_path}...")
    with open(input_path, 'r', encoding='utf-8') as f:
        content = f.read()

    print(f"  {len(content)} characters, splitting into chapters...")
    chapters = split_into_chapters(content)
    print(f"  Found {len(chapters)} chapter(s)")

    book_id = f"urn:uuid:{hash(input_path + title) & 0xFFFFFFFFFFFFFFFF:016x}"
    now_str = datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

    # --- Build the EPUB in memory ---
    buf = io.BytesIO()
    zf = zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED)

    # 1. mimetype (must be first, uncompressed, no extra fields)
    info = zipfile.ZipInfo('mimetype')
    info.compress_type = zipfile.ZIP_STORED
    info.external_attr = 0o644 << 16
    zf.writestr(info, 'application/epub+zip')

    # 2. META-INF/container.xml
    container_xml = '''<?xml version="1.0" encoding="UTF-8"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
  <rootfiles>
    <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>
  </rootfiles>
</container>'''
    zf.writestr('META-INF/container.xml', container_xml)

    # 3. CSS
    css = '''
@namespace epub "http://www.idpf.org/2007/ops";
body {
  font-family: Georgia, "Times New Roman", serif;
  line-height: 1.6;
  margin: 2em 1.5em;
  color: #1a1a1a;
  max-width: 30em;
}
h1 {
  text-align: center;
  font-size: 1.8em;
  margin-top: 2em;
  margin-bottom: 1em;
  page-break-before: always;
  font-weight: bold;
}
h2 {
  text-align: center;
  font-size: 1.4em;
  margin-top: 2em;
  margin-bottom: 1em;
  page-break-before: always;
  font-weight: bold;
}
h3 {
  text-align: left;
  font-size: 1.2em;
  margin-top: 1.5em;
  margin-bottom: 0.75em;
  font-weight: bold;
}
p {
  margin: 0.5em 0;
  text-indent: 1.5em;
  orphans: 2;
  widows: 2;
}
p.first {
  text-indent: 0;
}
blockquote {
  font-style: italic;
  margin: 1em 2em;
  color: #444;
}
em, i {
  font-style: italic;
}
strong, b {
  font-weight: bold;
}
.cover-page {
  page-break-before: always;
  page-break-after: always;
  text-align: center;
  padding-top: 30%;
}
.title-page {
  page-break-before: always;
  page-break-after: always;
  text-align: center;
  padding-top: 25%;
}
.title-page h1 {
  font-size: 2.2em;
  margin-bottom: 0.3em;
}
.title-page .author {
  font-size: 1.3em;
  margin-top: 1.5em;
}
.copyright-page {
  page-break-before: always;
  page-break-after: always;
  font-size: 0.85em;
  color: #555;
  padding-top: 10%;
}
.toc-page {
  page-break-before: always;
}
.toc-page h2 {
  text-align: center;
}
.toc-page ul {
  list-style: none;
  padding: 0;
}
.toc-page li {
  margin: 0.5em 0;
}
.chapter-title {
  text-align: center;
  font-size: 1.6em;
  margin-top: 3em;
  margin-bottom: 1.5em;
  page-break-before: always;
}
img {
  max-width: 100%;
  height: auto;
}
'''
    zf.writestr('OEBPS/css/style.css', css)

    # 4. XHTML files for each chapter
    spine_items = []
    manifest_items = []

    # Cover page
    cover_xhtml = '''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops" lang="''' + language + '''">
<head><title>Cover</title>
<link rel="stylesheet" type="text/css" href="css/style.css"/>
</head>
<body>
<div class="cover-page">
<h1>''' + xml_escape(title) + '''</h1>
<p class="author">''' + xml_escape(author) + '''</p>
</div>
</body>
</html>'''
    zf.writestr('OEBPS/xhtml/cover.xhtml', cover_xhtml)
    manifest_items.append('<item id="cover" href="xhtml/cover.xhtml" media-type="application/xhtml+xml"/>')
    spine_items.append('<itemref idref="cover"/>')

    if cover_image and os.path.exists(cover_image):
        # Add cover image to manifest
        ext = os.path.splitext(cover_image)[1].lower()
        mime = 'image/png' if ext == '.png' else 'image/jpeg' if ext in ('.jpg', '.jpeg') else 'image/webp'
        zf.writestr(f'OEBPS/images/cover{ext}', open(cover_image, 'rb').read())
        manifest_items.append(f'<item id="cover-image" href="images/cover{ext}" media-type="{mime}" properties="cover-image"/>')

    # Title page
    title_xhtml = '''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops" lang="''' + language + '''">
<head><title>Title Page</title>
<link rel="stylesheet" type="text/css" href="css/style.css"/>
</head>
<body>
<div class="title-page">
<h1>''' + xml_escape(title) + '''</h1>
<p class="author">''' + xml_escape(author) + '''</p>
</div>
</body>
</html>'''
    zf.writestr('OEBPS/xhtml/titlepage.xhtml', title_xhtml)
    manifest_items.append('<item id="titlepage" href="xhtml/titlepage.xhtml" media-type="application/xhtml+xml"/>')
    spine_items.append('<itemref idref="titlepage"/>')

    # Process chapters
    chapter_files = []
    for i, (ch_title, ch_body) in enumerate(chapters):
        # Skip very short items that look like front matter
        is_frontmatter = False
        tidy_title = ch_title.strip()
        if not tidy_title:
            tidy_title = f"Section {i+1}"

        # Convert markdown to HTML
        html_body = md_to_html_safe(ch_body)

        # Add chapter class to first h1/h2
        html_body = html_body.replace('<h1>', '<h1 class="chapter-title">', 1) if '<h1>' in html_body else html_body
        html_body = html_body.replace('<h2>', '<h2 class="chapter-title">', 1) if '<h2>' in html_body else html_body

        # Wrap in XHTML
        slug = slugify(tidy_title)
        if not slug:
            slug = f"chapter-{i+1:02d}"
        filename = f"chapter_{i+1:02d}_{slug}.xhtml"

        ch_xhtml = '''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops" lang="''' + language + '''">
<head><title>''' + xml_escape(tidy_title) + '''</title>
<link rel="stylesheet" type="text/css" href="css/style.css"/>
</head>
<body>
''' + html_body + '''
</body>
</html>'''

        zf.writestr(f'OEBPS/xhtml/{filename}', ch_xhtml)
        manifest_items.append(f'<item id="{slug}" href="xhtml/{filename}" media-type="application/xhtml+xml"/>')
        spine_items.append(f'<itemref idref="{slug}"/>')
        chapter_files.append((tidy_title, filename))

    # 5. Navigation document
    nav_items = ''.join(f'<li><a href="xhtml/{f}">{xml_escape(t)}</a></li>\n' for t, f in chapter_files)

    nav_xhtml = '''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops" lang="''' + language + '''">
<head><title>Table of Contents</title>
<link rel="stylesheet" type="text/css" href="css/style.css"/>
</head>
<body class="toc-page">
<nav xmlns:epub="http://www.idpf.org/2007/ops" epub:type="toc">
<h2>Table of Contents</h2>
<ul>
<li><a href="xhtml/cover.xhtml">Cover</a></li>
<li><a href="xhtml/titlepage.xhtml">Title Page</a></li>
''' + nav_items + '''
</ul>
</nav>
</body>
</html>'''
    zf.writestr('OEBPS/nav.xhtml', nav_xhtml)
    manifest_items.append('<item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>')

    # 6. content.opf
    manifest_xml = '\n    '.join(manifest_items)
    spine_xml = '\n    '.join(spine_items)

    opf = '''<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="book-id">
  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:opf="http://www.idpf.org/2007/opf">
    <dc:identifier id="book-id">''' + xml_escape(book_id) + '''</dc:identifier>
    <dc:title>''' + xml_escape(title) + '''</dc:title>
    <dc:creator id="creator">''' + xml_escape(author) + '''</dc:creator>
    <dc:language>''' + language + '''</dc:language>
    <dc:date>''' + now_str + '''</dc:date>
    <meta property="dcterms:modified">''' + now_str + '''</meta>
    <meta name="generator" content="Hermes Agent EPUB Converter"/>
  </metadata>
  <manifest>
    <item id="css" href="css/style.css" media-type="text/css"/>
    ''' + manifest_xml + '''
  </manifest>
  <spine>
    ''' + spine_xml + '''
  </spine>
</package>'''

    zf.writestr('OEBPS/content.opf', opf)
    zf.close()

    # Write the epub file
    with open(output_path, 'wb') as f:
        f.write(buf.getvalue())

    size = os.path.getsize(output_path)
    print(f"  Created: {output_path} ({size/1024:.1f} KB)")
    return True

# --- Main ---
if __name__ == '__main__':
    if len(sys.argv) < 5:
        print("Usage: python3 convert_to_epub.py <input.md> <output.epub> <title> <author> [cover.png]")
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2]
    title = sys.argv[3]
    author = sys.argv[4]
    cover = sys.argv[5] if len(sys.argv) > 5 else None

    if not os.path.exists(input_path):
        print(f"ERROR: Input file not found: {input_path}")
        sys.exit(1)

    success = create_epub(input_path, output_path, title, author, cover)
    sys.exit(0 if success else 1)
